/**
 * scripts/build-zcode-hooks.ts — build the ZCode process-hook bundles
 * (root script `hooks:build`; cross-host hooks contract D2).
 *
 * Bundles the ZCode process hooks with `bun build --target node` (the hooks
 * run via `"command": "node"` in hooks/hooks.json) into committed artifacts.
 * The ZCode plugin root IS the repo checkout and the plugin pipeline has no
 * build step, so artifacts are committed under a `@generated` banner; CI
 * enforces freshness (`bun run engine:build && bun run hooks:build && git diff
 * --exit-code -- hooks/`). The `@mstar-harness/engine` glue is inlined — no
 * bare engine import may survive.
 *
 * Repo convention: same-name test (scripts/build-zcode-hooks.test.ts) wired
 * into the CI "Test scripts" step.
 */
import { statSync } from "node:fs";
import { join, relative, resolve } from "node:path";

const ROOT = resolve(import.meta.dir, "..");

export const HOOK_ENTRIES = [
  { entry: "hooks/src/mstar-write-gate.ts", outfile: "hooks/mstar-write-gate.mjs" },
  { entry: "hooks/src/session-context.ts", outfile: "hooks/session-context.mjs" },
] as const;
export const HOOK_OUTFILE_REL = HOOK_ENTRIES[0].outfile;

/** Banner prepended to each bundle; names the source and regeneration path. */
export const GENERATED_BANNER = (entry: string) =>
  `#!/usr/bin/env node\n// @generated by scripts/build-zcode-hooks.ts from ${entry} - do not edit; rebuild with \`bun run hooks:build\`.\n`;

/** Rebuild the committed ZCode hook bundles in place. Deterministic output is
 * load-bearing: the CI freshness gate diffs the working tree against them. */
export async function buildZcodeHooks(): Promise<{ outfile: string; bytes: number }[]> {
  const built: { outfile: string; bytes: number }[] = [];
  for (const { entry, outfile: outfileRel } of HOOK_ENTRIES) {
    const result = await Bun.build({
      entrypoints: [join(ROOT, entry)],
      target: "node",
      banner: GENERATED_BANNER(entry),
    });
    if (!result.success) {
      const detail = result.logs.map((log) => String(log)).join("\n");
      throw new Error(`hooks:build failed for ${entry}:\n${detail}`);
    }
    const entryArtifact = result.outputs.find((output) => output.kind === "entry-point");
    if (entryArtifact === undefined) throw new Error(`hooks:build produced no entry-point artifact for ${entry}`);
    const outfile = join(ROOT, outfileRel);
    await Bun.write(outfile, entryArtifact);
    built.push({ outfile, bytes: statSync(outfile).size });
  }
  return built;
}

if (import.meta.main) {
  const outputs = await buildZcodeHooks();
  for (const { outfile, bytes } of outputs) {
    console.log(`hooks:build: ${relative(ROOT, outfile)} (${bytes} bytes, engine inlined)`);
  }
}
